e-js":"var firstTab = document.querySelector(\'#tabs_contents-4280 > .oxy-tabs-contents-content-hidden:first-child\');\\nif(firstTab && firstTab.classList){\\n  firstTab.classList.remove(\\"oxy-tabs-contents-content-hidden\\")\\n};\\n\\njQuery(\\"body\\").on(\'click\', \'.oxy-tabs-wrapper > div\', function(e) {\\n    \\/* a tab or an element that is a child of a tab has been clicked. prevent any default behavior *\\/\\n    \\/\\/e.preventDefault();\\n\\n    \\/* which tab has been clicked? (e.target might be a child of the tab.) *\\/\\n    clicked_tab = jQuery(e.target).closest(\'.oxy-tabs-wrapper > div\');\\n    index = clicked_tab.index();\\n\\n    \\/* which tabs-wrapper is this tab inside? *\\/\\n    tabs_wrapper = jQuery(e.target).closest(\'.oxy-tabs-wrapper\');\\n\\n    \\/* what class dp we use to signify an active tob? *\\/\\n    class_for_active_tab = tabs_wrapper.attr(\'data-oxy-tabs-active-tab-class\');\\n\\n    \\/* make all the other tabs in this tabs-wrapper inactive *\\/\\n    jQuery(tabs_wrapper).children(\'.oxy-tabs-wrapper > div\').removeClass(class_for_active_tab);\\n\\n    \\/* make the clicked tab the active tab *\\/\\n    jQuery(tabs_wrapper).children(\'.oxy-tabs-wrapper > div\').eq(index).addClass(class_for_active_tab);\\n\\n    \\/* which tabs-contents-wrapper is used by these tabs? *\\/\\n    tabs_contents_wrapper_id = tabs_wrapper.attr(\'data-oxy-tabs-contents-wrapper\');\\n\\n    \\/* try to grab the correct content wrapper, in case of duplicated ID\'s *\\/\\n    $content_wrapper = jQuery(tabs_wrapper).next();\\n    if ($content_wrapper.attr(\\"id\\") != tabs_contents_wrapper_id)\\n        $content_wrapper = jQuery(\'#\' + tabs_contents_wrapper_id);\\n\\n    $content_tabs = $content_wrapper.children(\\"div\\");\\n\\n    \\/* hide all of the content *\\/\\n    $content_tabs.addClass(\'oxy-tabs-contents-content-hidden\');\\n\\n    \\/* unhide the content corresponding to the active tab*\\/\\n    $content_tabs.eq(index).removeClass(\'oxy-tabs-contents-content-hidden\');\\n\\n});","code-css":""},"nicename":"Code Block (#4034)","activeselector":false,"classes":[]},"depth":3}]}]}]},{"id":54,"name":"ct_section","options":{"ct_id":54,"ct_parent":0,"selector":"arquivos","original":{"background-color":"#e9edf2","container-padding-top":"40","container-padding-bottom":"50","custom-css":""},"nicename":"Arquivos","activeselector":false},"depth":1,"children":[{"id":5241,"name":"ct_div_block","options":{"ct_id":5241,"ct_parent":54,"selector":"div_block-5241-15","original":{"width":"100","width-unit":"%","text-align":"left","align-items":"center","gap":"10","margin-bottom":"10"},"nicename":"Div (#5241)","activeselector":false},"depth":2,"children":[{"id":5235,"name":"ct_link","options":{"ct_id":5235,"ct_parent":5241,"selector":"link-5235-15","original":{"url":"http:\\/\\/localhost\\/frellas\\/prefeitura-lassance\\/arquivos\\/","target":"","width-unit":"%"},"nicename":"Link Wrapper (#5235)","activeselector":"ver-todos","classes":["ver-todos"]},"depth":3,"children":[{"id":5236,"name":"ct_headline","options":{"ct_id":5236,"ct_parent":5235,"selector":"headline-5236-15","original":{"tag":"h2","color":"#2048cc","font-family":"Montserrat","font-size":"22","font-weight":"600","line-height":"1.2","width-unit":"%","text-align":"center","border-top-width-unit":"","border-right-width-unit":"","border-bottom-width-unit":"","border-left-width-unit":"","border-all-width-unit":""},"nicename":"Heading (#19)","ct_content":"Arquivos","activeselector":false,"classes":[]},"depth":4}]},{"id":5239,"name":"ct_div_block","options":{"ct_id":5239,"ct_parent":5241,"selector":"div_block-5239-15","original":{"width":"100","width-unit":"%","height":"5","background-color":"#ffffff","max-height":"5","padding-top":"0","padding-right":"0","padding-bottom":"0","padding-left":"0"},"nicename":"Div (#5239)","activeselector":false},"depth":3}]},{"id":1726,"name":"ct_div_block","options":{"ct_id":1726,"ct_parent":54,"selector":"div_block-1726-15","classes":