tainer\').append(pagination);\\n\\tjQuery(\'.swiper-container\').append(prevnext);\\n\\n\\tif( typeof Swiper == \'undefined\' ) { return; }\\n\\n\\tvar swiper1 = new Swiper(\'.swiper-container-banner\', {\\n\\t\\tloop: true,\\n        noSwiping: false,\\n\\t\\teffect: transition,\\n        autoplay: {\\n    \\t\\tdelay: delay,\\n    \\t\\tdisableOnInteraction: true,\\n\\t\\t},\\n\\t\\tpagination: {\\n    \\t\\tel: \'.swiper-pagination\',\\n    \\t\\tclickable: true,\\n\\t\\t},\\n\\t\\tnavigation: {\\n    \\t\\tnextEl: \'.swiper-button-next\',\\n    \\t\\tprevEl: \'.swiper-button-prev\',\\n\\t\\t}\\n\\t});\\n\\n\\tvar swiper2 = new Swiper(\'.swiper-container-arquivos\', {\\n\\t\\tslidesPerView: 3,\\n\\t\\tspaceBetween: 20,\\n        noSwiping: false,\\n\\t\\teffect: transition,\\n\\t\\tpagination: false,\\n\\t\\tnavigation: {\\n    \\t\\tnextEl: \'.swiper-button-next\',\\n    \\t\\tprevEl: \'.swiper-button-prev\',\\n\\t\\t},\\n\\t\\tbreakpoints: {\\n          992: {\\n            slidesPerView: 3,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          768: {\\n            slidesPerView: 2,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          0: {\\n            slidesPerView: 1,\\n\\t\\t    spaceBetween: 20,\\n          }\\n        }\\n\\t});\\n\\n\\tvar swiper3 = new Swiper(\'.swiper-container-videos\', {\\n\\t\\tslidesPerView: 4,\\n\\t\\tspaceBetween: 20,\\n        noSwiping: false,\\n\\t\\teffect: transition,\\n\\t\\tpagination: false,\\n\\t\\tnavigation: {\\n    \\t\\tnextEl: \'.swiper-button-next\',\\n    \\t\\tprevEl: \'.swiper-button-prev\',\\n\\t\\t},\\n        breakpoints: {\\n          1200: {\\n            slidesPerView: 4,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          992: {\\n            slidesPerView: 3,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          768: {\\n            slidesPerView: 2,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          0: {\\n            slidesPerView: 1,\\n\\t\\t    spaceBetween: 20,\\n          }\\n        }\\n\\t});\\n\\n    var swiper4 = new Swiper(\'.swiper-container-projetos\', {\\n\\t\\tslidesPerView: 1,\\n\\t\\tspaceBetween: 10,\\n        noSwiping: false,\\n\\t\\teffect: transition,\\n\\t\\tpagination: {\\n    \\t\\tel: \'.swiper-pagination\',\\n    \\t\\tclickable: true,\\n        }\\n\\t});\\n\\n    var swiper5 = new Swiper(\'.swiper-container-fotos\', {\\n\\t\\tslidesPerView: 3,\\n\\t\\tspaceBetween: 20,\\n        noSwiping: false,\\n\\t\\teffect: transition,\\n\\t\\tpagination: false,\\n\\t\\tnavigation: {\\n    \\t\\tnextEl: \'.swiper-button-next\',\\n    \\t\\tprevEl: \'.swiper-button-prev\',\\n\\t\\t},\\n\\t\\tbreakpoints: {\\n          992: {\\n            slidesPerView: 3,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          768: {\\n            slidesPerView: 2,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          580: {\\n            slidesPerView: 2,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          0: {\\n            slidesPerView: 1,\\n\\t\\t    spaceBetween: 20,\\n          }\\n        }\\n\\t});\\n\\n\\tvar swiper6 = new Swiper(\'.swiper-container-secretarias\', {\\n\\t\\tslidesPerView: 5,\\n\\t\\tspaceBetween: 20,\\n\\t\\tnoSwiping: false,\\n\\t\\teffect: transition,\\n\\t\\tpagination: false,\\n\\t\\tnavigation: {\\n    \\t\\tnextEl: \'.swiper-button-next\',\\n    \\t\\tprevEl: \'.swiper-button-prev\',\\n\\t\\t},\\n        breakpoints: {\\n          1200: {\\n            slidesPerView: 5,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          992: {\\n            slidesPerView: 4,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          768: {\\n            slidesPerView: 3,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          580: {\\n            slidesPerView: 2,\\n\\t\\t    spaceBetween: 20,\\n          },\\n          0: {\\n            slidesPerView: 1,\\n\\t\\t    spaceBetween: 20,\\n          }\\n        }\\n\\t});\\n\\n    var swiper7 = new Swiper(\'.swiper-container-previsao\', {\\n\\t\\tslidesPerView: 6,\\n