ed tab the active tab *\\/\\n    jQuery(tabs_wrapper).children(\'.oxy-tabs-wrapper > div\').eq(index).addClass(class_for_active_tab);\\n\\n    \\/* which tabs-contents-wrapper is used by these tabs? *\\/\\n    tabs_contents_wrapper_id = tabs_wrapper.attr(\'data-oxy-tabs-contents-wrapper\');\\n\\n    \\/* try to grab the correct content wrapper, in case of duplicated ID\'s *\\/\\n    $content_wrapper = jQuery(tabs_wrapper).next();\\n    if ($content_wrapper.attr(\\"id\\") != tabs_contents_wrapper_id)\\n        $content_wrapper = jQuery(\'#\' + tabs_contents_wrapper_id);\\n\\n    $content_tabs = $content_wrapper.children(\\"div\\");\\n\\n    \\/* hide all of the content *\\/\\n    $content_tabs.addClass(\'oxy-tabs-contents-content-hidden\');\\n\\n    \\/* unhide the content corresponding to the active tab*\\/\\n    $content_tabs.eq(index).removeClass(\'oxy-tabs-contents-content-hidden\');\\n\\n});","code-css":""},"nicename":"Code Block (#4034)","activeselector":false,"classes":[]},"depth":3}]}]}]},{"id":54,"name":"ct_section","options":{"ct_id":54,"ct_parent":0,"selector":"arquivos","original":{"background-color":"#e9edf2","container-padding-top":"40","container-padding-bottom":"50","custom-css":""},"nicename":"Arquivos","activeselector":false},"depth":1,"children":[{"id":5241,"name":"ct_div_block","options":{"ct_id":5241,"ct_parent":54,"selector":"div_block-5241-15","original":{"width":"100","width-unit":"%","text-align":"left","align-items":"center","gap":"10","margin-bottom":"10"},"nicename":"Div (#5241)","activeselector":false},"depth":2,"children":[{"id":5235,"name":"ct_link","options":{"ct_id":5235,"ct_parent":5241,"selector":"link-5235-15","original":{"url":"http:\\/\\/localhost\\/frellas\\/prefeitura-lassance\\/arquivos\\/","target":"","width-unit":"%"},"nicename":"Link Wrapper (#5235)","activeselector":"ver-todos","classes":["ver-todos"]},"depth":3,"children":[{"id":5236,"name":"ct_headline","options":{"ct_id":5236,"ct_parent":5235,"selector":"headline-5236-1