	(359, 1, '2025-03-12 15:00:01', '2025-03-12 18:00:01', '<!-- wp:image {"id":344,"width":"840px","height":"auto","sizeSlug":"large","linkDestination":"none"} -->\n<figure class="wp-block-image size-large is-resized"><img src="http://localhost/frellas/prefeitura-lassance/wp-content/uploads/2025/03/crianca-feliz-819x1024.jpg" alt="" class="wp-image-344" style="width:840px;height:auto"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><br><strong><a href="http://localhost/frellas/prefeitura-lassance/wp-content/uploads/2025/03/EDITAL-02-2025-PROCESSO-SELETIVO-CRIANCA-FELIZ-LASSANCE.pdf" data-type="link" data-id="http://localhost/frellas/prefeitura-lassance/wp-content/uploads/2025/03/EDITAL-02-2025-PROCESSO-SELETIVO-CRIANCA-FELIZ-LASSANCE.pdf">Acesse aqui o edital do Processo Seletivo Criança Feliz.</a></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Processo Seletivo Criança Feliz', '', 'inherit', 'closed', 'closed', '', '343-revision-v1', '', '', '2025-03-12 15:00:01', '2025-03-12 18:00:01', '', 343, 'http://localhost/frellas/prefeitura-lassance/?p=359', 0, 'revision', '', 0),
